// 第37回 Aパート 問題1-6 (EPA版). Jawaban resmi: MHLW. Penjelasan: PahamKaigo.
(function (d) { var K = window.PK_KAKOMON = window.PK_KAKOMON || {}; Object.keys(d).forEach(function (s) { K[s] = K[s] || {}; Object.keys(d[s]).forEach(function (y) { K[s][y] = (K[s][y] || []).concat(d[s][y]).sort(function (a, b) { return a.no - b.no; }); }); }); })({"songen":{"37":[{"no":1,"jp":"{次|つぎ}の{記述|きじゅつ}のうち，{介護福祉職|かいごふくししょく}がアドボカシー（advocacy）の{視点|してん}から{行|おこな}う{対応|たいおう}として，{最|もっと}も{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Pilih 1 tindakan yang paling tepat dilakukan pekerja kaigo dari sudut pandang advokasi (advocacy).","answer":3,"opts":[{"jp":"{介護|かいご}を{行|おこな}う{前|まえ}には，{利用者|りようしゃ}に{十分|じゅうぶん}な{説明|せつめい}をして{同意|どうい}を{得|え}る。","id":"Sebelum merawat, menjelaskan dengan cukup kepada pengguna dan mendapat persetujuannya.","reason":"Ini adalah informed consent (persetujuan setelah penjelasan). Penting, tetapi bukan inti advokasi."},{"jp":"{利用者|りようしゃ}の{介護計画|かいごけいかく}を{作成|さくせい}するときに，{他職種|たしょくしゅ}に{専門的|せんもんてき}な{助言|じょげん}を{求|もと}める。","id":"Saat membuat rencana perawatan, meminta saran profesional dari profesi lain.","reason":"Ini adalah kerja sama multi-profesi ({多職種連携|たしょくしゅれんけい}), bukan advokasi."},{"jp":"{利用者個人|りようしゃこじん}の{趣味|しゅみ}を{生|い}かして，レクリエーション{活動|かつどう}を{行|おこな}う。","id":"Mengadakan kegiatan rekreasi dengan memanfaatkan hobi pribadi pengguna.","reason":"Ini adalah perawatan individual yang menghargai pengguna, tetapi bukan mewakili suara pengguna."},{"jp":"{希望|きぼう}を{言|い}い{出|だ}しにくい{利用者|りようしゃ}の{意思|いし}をくみ{取|と}り，その{実現|じつげん}に{向|む}けて{働|はたら}きかける。","id":"Memahami keinginan pengguna yang sulit menyampaikan harapannya, lalu berusaha agar keinginan itu terwujud.","reason":"Benar. Advokasi berarti mewakili ({代弁|だいべん}) suara pengguna yang sulit menyampaikan keinginan atau haknya, lalu memperjuangkan agar terwujud."},{"jp":"{視覚障害者|しかくしょうがいしゃ}が{必要|ひつよう}とする{情報|じょうほう}を，{利用|りよう}しやすいようにする。","id":"Membuat informasi yang dibutuhkan penyandang tunanetra mudah digunakan.","reason":"Ini adalah jaminan aksesibilitas informasi ({情報保障|じょうほうほしょう}), bukan inti advokasi."}],"explain":"Advokasi (アドボカシー) = {権利擁護|けんりようご}・{代弁|だいべん}. Pekerja kaigo mewakili dan memperjuangkan keinginan serta hak pengguna yang sulit menyuarakan dirinya sendiri. Kata kunci di soal: {意思|いし}をくみ{取|と}る (memahami keinginan) dan {代弁|だいべん} (menyuarakan atas nama pengguna)."},{"no":2,"jp":"Ａさん（83{歳|さい}，{女性|じょせい}，{要介護|ようかいご}3）は，{脳梗塞|のうこうそく}（cerebral infarction）の{後遺症|こういしょう}で{左片麻痺|ひだりかたまひ}があり，{介護老人福祉施設|かいごろうじんふくししせつ}で{生活|せいかつ}している。{家族|かぞく}から，「できることは{自分|じぶん}で{行|おこな}ってほしい」と{希望|きぼう}があり，Ａさんは{自室|じしつ}から{食堂|しょくどう}まで{車|くるま}いすで{自走|じそう}することを{日課|にっか}としている。1{週間前|しゅうかんまえ}から，{介護福祉士養成施設|かいごふくししようせいしせつ}の{学生|がくせい}がＡさんのフロアで{実習|じっしゅう}を{開始|かいし}した。{数日前|すうじつまえ}からＡさんは{実習生|じっしゅうせい}に，「{今日|きょう}は{腕|うで}が{痛|いた}いので，{食堂|しょくどう}まで{車|くるま}いすを{押|お}してください」と{依頼|いらい}するようになった。{悩|なや}んだ{実習生|じっしゅうせい}は，{実習指導者|じっしゅうしどうしゃ}に{相談|そうだん}をした。{実習生|じっしゅうせい}に{対|たい}する{実習指導者|じっしゅうしどうしゃ}の{最初|さいしょ}の{助言|じょげん}として，{最|もっと}も{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Bu A (83 th, wanita, butuh perawatan tingkat 3) lumpuh separuh kiri akibat infark otak dan tinggal di panti lansia khusus. Keluarga berharap \"yang bisa dilakukan sendiri, lakukan sendiri\", jadi Bu A setiap hari menjalankan kursi roda sendiri dari kamar ke ruang makan. Sejak 1 minggu lalu, mahasiswa sekolah kaigo mulai praktik di lantai Bu A. Beberapa hari ini Bu A meminta mahasiswa itu: \"Hari ini lengan saya sakit, tolong dorong kursi roda saya ke ruang makan.\" Mahasiswa yang bingung berkonsultasi ke pembimbing praktik. Pilih 1 saran pertama yang paling tepat dari pembimbing.","answer":4,"opts":[{"jp":"「Ａさんの{腕|うで}は{痛|いた}くないので，{気|き}にしないでください」","id":"\"Lengan Bu A sebenarnya tidak sakit, jadi tidak usah dipikirkan.\"","reason":"Salah. Menyimpulkan tanpa dasar bahwa pengguna tidak sakit berarti tidak menghormati perasaan dan keluhan pengguna."},{"jp":"「どのようなときも，Ａさん{自身|じしん}で{行|おこな}ってもらうことが{必要|ひつよう}です」","id":"\"Dalam keadaan apa pun, Bu A harus melakukannya sendiri.\"","reason":"Salah. Kemandirian bukan berarti memaksa. Kalau ada alasan (misalnya sakit), bantuan bisa dibutuhkan."},{"jp":"「ご{家族|かぞく}から{自分|じぶん}で{行|おこな}うように，{言|い}われています」","id":"\"Keluarga sudah minta agar Bu A melakukannya sendiri.\"","reason":"Salah. Ini mengutamakan keinginan keluarga dan mengabaikan keinginan serta keadaan Bu A sendiri."},{"jp":"「それは{自立|じりつ}につながらないので，{車|くるま}いすを{押|お}さないでください」","id":"\"Itu tidak mendukung kemandirian, jadi jangan dorong kursi rodanya.\"","reason":"Salah. Langsung menolak tanpa mencari tahu alasan permintaan Bu A tidak tepat sebagai saran pertama."},{"jp":"「Ａさんが{依頼|いらい}する{理由|りゆう}を，まず{考|かんが}えてみることが{大切|たいせつ}です」","id":"\"Yang penting, pertama-tama pikirkan dulu alasan Bu A meminta bantuan.\"","reason":"Benar. Langkah pertama adalah memahami latar belakang permintaan: apakah benar sakit, ingin berbicara dengan mahasiswa, merasa kesepian, dan sebagainya. Setelah itu baru ditentukan bantuannya."}],"explain":"Kata kunci {最初|さいしょ}の{助言|じょげん} (saran pertama). Sebelum memutuskan membantu atau menolak, pekerja kaigo harus memahami dulu alasan dan perasaan pengguna di balik permintaannya. Ini sesuai dengan prinsip menghormati martabat dan dukungan kemandirian ({自立支援|じりつしえん}) yang tidak memaksa."}]},"kankei":{"37":[{"no":3,"jp":"{人間関係|にんげんかんけい}と{心理|しんり}に{関|かん}する{次|つぎ}の{記述|きじゅつ}のうち，{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Pilih 1 pernyataan yang tepat tentang hubungan antarmanusia dan psikologi.","answer":1,"opts":[{"jp":"{自己愛|じこあい}とは，{自分|じぶん}という{存在|そんざい}を，{他人|たにん}と{区別|くべつ}して{意識|いしき}することである。","id":"Cinta diri (narsisme) adalah menyadari keberadaan diri sendiri sebagai sesuatu yang berbeda dari orang lain.","reason":"Salah. Yang dijelaskan adalah kesadaran diri ({自己意識|じこいしき}). {自己愛|じこあい} adalah rasa cinta dan menghargai diri sendiri."},{"jp":"{自己同一性|じこどういつせい}の{確立|かくりつ}とは，{自分|じぶん}とは{何|なに}かという{認識|にんしき}をもつことである。","id":"Terbentuknya identitas diri adalah memiliki pemahaman tentang \"siapa diri saya\".","reason":"Benar. {自己同一性|じこどういつせい} (identitas diri / アイデンティティ) adalah pemahaman tentang siapa diri kita. Menurut Erikson, ini adalah tugas perkembangan masa remaja."},{"jp":"{自我|じが}とは，{日常行動|にちじょうこうどう}に{影響|えいきょう}を{与|あた}える，{表面化|ひょうめんか}していない{意識|いしき}のことである。","id":"Ego adalah kesadaran yang tidak muncul ke permukaan, yang memengaruhi perilaku sehari-hari.","reason":"Salah. Kesadaran yang tidak muncul ke permukaan adalah alam bawah sadar ({無意識|むいしき}). {自我|じが} (ego) adalah bagian diri yang menyadari dan mengatur pikiran serta tindakan."},{"jp":"{自己覚知|じこかくち}とは，コミュニケーションにおいて{自分|じぶん}について{話|はな}すことである。","id":"Kesadaran diri (self-awareness) adalah menceritakan tentang diri sendiri dalam komunikasi.","reason":"Salah. Menceritakan diri sendiri adalah {自己開示|じこかいじ} (keterbukaan diri). {自己覚知|じこかくち} adalah memahami nilai, perasaan, dan kebiasaan diri sendiri secara objektif."},{"jp":"{自己中心性|じこちゅうしんせい}とは，{自分|じぶん}の{意思|いし}で{自分|じぶん}の{行動|こうどう}をコントロールすることである。","id":"Egosentrisme adalah mengendalikan tindakan sendiri dengan kehendak sendiri.","reason":"Salah. Mengendalikan diri adalah {自己|じこ}コントロール (kontrol diri). {自己中心性|じこちゅうしんせい} adalah sulit melihat sesuatu dari sudut pandang orang lain (khas anak usia praoperasional menurut Piaget)."}],"explain":"Bedakan istilah yang mirip: {自己同一性|じこどういつせい} = identitas diri (siapa saya), {自己覚知|じこかくち} = memahami diri secara objektif, {自己開示|じこかいじ} = menceritakan diri ke orang lain, {自己中心性|じこちゅうしんせい} = sulit melihat dari sudut pandang orang lain, {無意識|むいしき} = alam bawah sadar."},{"no":4,"jp":"Ａさん（80{歳|さい}，{男性|だんせい}）は，{有料老人|ゆうりょうろうじん}ホームに{入所|にゅうしょ}することになった。{一人暮|ひとりぐ}らしが{長|なが}かったＡさんは，{入所当日|にゅうしょとうじつ}，{担当|たんとう}の{介護福祉職|かいごふくししょく}と{話|はな}すことに{戸惑|とまど}っている{様子|ようす}で，なかなか{自分|じぶん}のことを{話|はな}そうとはしなかった。{介護福祉職|かいごふくししょく}は，{一方的|いっぽうてき}な{働|はたら}きかけにならないように，Ａさんとコミュニケーションをとるとき，あいづちを{打|う}ちながらＡさんの{発話|はつわ}を{引|ひ}き{出|だ}すように{心|こころ}がけた。このときの，{介護福祉職|かいごふくししょく}の{対応|たいおう}の{意図|いと}に{当|あ}てはまるものとして，{最|もっと}も{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Pak A (80 th, pria) masuk panti lansia berbayar. Karena lama hidup sendiri, pada hari pertama ia tampak canggung berbicara dengan pekerja kaigo penanggung jawabnya dan tidak mau bercerita tentang dirinya. Agar tidak sepihak, pekerja kaigo berusaha memancing Pak A berbicara sambil memberi tanggapan singkat (aizuchi). Pilih 1 maksud tindakan pekerja kaigo yang paling tepat.","answer":4,"opts":[{"jp":"{互|たが}いの{自己開示|じこかいじ}","id":"Saling terbuka tentang diri sendiri","reason":"Salah. Pekerja kaigo tidak sedang menceritakan dirinya, tetapi memancing Pak A berbicara."},{"jp":"コミュニケーション{能力|のうりょく}の{評価|ひょうか}","id":"Menilai kemampuan komunikasi","reason":"Salah. Tujuannya bukan menilai kemampuan, tetapi membangun percakapan."},{"jp":"{感覚機能|かんかくきのう}の{低下|ていか}への{配慮|はいりょ}","id":"Memperhatikan penurunan fungsi indra","reason":"Salah. Di soal tidak ada keterangan Pak A mengalami gangguan pendengaran atau penglihatan."},{"jp":"{認知機能|にんちきのう}の{改善|かいぜん}","id":"Memperbaiki fungsi kognitif","reason":"Salah. Di soal tidak ada masalah fungsi kognitif, dan aizuchi bukan untuk memperbaikinya."},{"jp":"{双方向|そうほうこう}のやり{取|と}り","id":"Komunikasi dua arah","reason":"Benar. Dengan aizuchi dan memancing Pak A berbicara, komunikasi tidak sepihak ({一方的|いっぽうてき}) tetapi menjadi dua arah ({双方向|そうほうこう}). Ini dasar membangun hubungan saling percaya (ラポール)."}],"explain":"Kata kunci di soal: {一方的|いっぽうてき}な{働|はたら}きかけにならないように (supaya tidak sepihak). Lawan kata {一方的|いっぽうてき} adalah {双方向|そうほうこう} (dua arah). あいづち (tanggapan singkat seperti \"un\", \"sou desu ne\") membantu pengguna merasa didengar dan mau berbicara."},{"no":5,"jp":"{次|つぎ}の{記述|きじゅつ}のうち，{介護福祉職|かいごふくししょく}のキャリアパスに{関|かん}するものとして，{最|もっと}も{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Pilih 1 pernyataan yang paling tepat tentang jalur karier (career path) pekerja kaigo.","answer":4,"opts":[{"jp":"{介護計画|かいごけいかく}を{作成|さくせい}するときのポイントを{明確|めいかく}にする。","id":"Memperjelas poin-poin saat membuat rencana perawatan.","reason":"Salah. Ini berkaitan dengan proses kaigo ({介護過程|かいごかてい}), bukan jalur karier."},{"jp":"{介護福祉職|かいごふくししょく}の{業務|ぎょうむ}マニュアルを{具体化|ぐたいか}する。","id":"Membuat manual kerja pekerja kaigo lebih konkret.","reason":"Salah. Manual kerja adalah standarisasi pekerjaan, bukan jalur karier."},{"jp":"{利用|りよう}サービスに{応|おう}じて{求|もと}められる{関係書類|かんけいしょるい}を{検討|けんとう}する。","id":"Meninjau dokumen yang dibutuhkan sesuai layanan yang digunakan.","reason":"Salah. Ini urusan administrasi dokumen, bukan jalur karier."},{"jp":"{介護施設|かいごしせつ}に{必要|ひつよう}な{設備基準|せつびきじゅん}について{確認|かくにん}する。","id":"Memeriksa standar fasilitas yang dibutuhkan panti kaigo.","reason":"Salah. Standar fasilitas adalah urusan pengelolaan panti, bukan jalur karier."},{"jp":"{介護福祉職|かいごふくししょく}として{必要|ひつよう}な{能力|のうりょく}や{経験|けいけん}を{明確|めいかく}にする。","id":"Memperjelas kemampuan dan pengalaman yang dibutuhkan sebagai pekerja kaigo.","reason":"Benar. キャリアパス adalah jalur untuk naik jabatan atau tingkat, dengan menjelaskan kemampuan, pengalaman, dan syarat yang dibutuhkan di setiap tahap."}],"explain":"キャリアパス (career path) = gambaran jalur karier: posisi atau tingkat apa yang bisa dicapai, serta kemampuan, pengalaman, dan pelatihan yang dibutuhkan untuk mencapainya. Ini juga berhubungan dengan {処遇改善加算|しょぐうかいぜんかさん} (tunjangan perbaikan perlakuan kerja)."},{"no":6,"jp":"Ｂ{介護老人福祉施設|かいごろうじんふくししせつ}に，{学校|がっこう}を{卒業|そつぎょう}したばかりの{元気|げんき}なＣ{介護福祉職|かいごふくししょく}が{加|くわ}わった。2か{月後|げつご}，ユニットリーダーが，「{最近|さいきん}，Ｃ{介護福祉職|かいごふくししょく}に{笑顔|えがお}が{少|すく}ない。いつもとちがう{様子|ようす}だ」と，フォロワーであるＤ{介護福祉職|かいごふくししょく}に{話|はな}した。Ｄ{介護福祉職|かいごふくししょく}はチームの{一員|いちいん}として{何|なに}ができるのかを{考|かんが}えた。Ｄ{介護福祉職|かいごふくししょく}が{最初|さいしょ}に{行|おこな}うフォロワーシップとして，{最|もっと}も{適切|てきせつ}なものを1つ{選|えら}びなさい。","id":"Di panti lansia khusus B, bergabung pekerja kaigo C yang ceria dan baru lulus sekolah. 2 bulan kemudian, ketua unit berkata kepada pekerja kaigo D (follower): \"Akhir-akhir ini C jarang tersenyum. Ia tampak berbeda dari biasanya.\" D memikirkan apa yang bisa ia lakukan sebagai anggota tim. Pilih 1 followership yang paling tepat dilakukan D pertama kali.","answer":1,"opts":[{"jp":"Ｃ{介護福祉職|かいごふくししょく}に{対|たい}して，{元気|げんき}を{出|だ}すように{励|はげ}ます。","id":"Menyemangati C supaya kembali ceria.","reason":"Salah. Menyemangati tanpa tahu keadaannya belum tentu membantu, dan ini bukan langkah pertama."},{"jp":"ユニットリーダーが{気|き}になっていることを{詳|くわ}しく{聞|き}く。","id":"Menanyakan lebih rinci apa yang dikhawatirkan ketua unit.","reason":"Benar. Followership dimulai dengan memahami maksud dan kekhawatiran pemimpin. Setelah informasinya jelas, D bisa membantu sesuai arah pemimpin."},{"jp":"Ｃ{介護福祉職|かいごふくししょく}の{状況|じょうきょう}をユニット{内|ない}のほかのメンバーと{速|すみ}やかに{共有|きょうゆう}する。","id":"Segera membagikan keadaan C ke anggota unit lainnya.","reason":"Salah. Informasinya belum jelas, dan menyebarkannya bisa melanggar privasi C."},{"jp":"{施設長|しせつちょう}に{対|たい}して，{何|なに}か{指示|しじ}を{出|だ}すようにお{願|ねが}いする。","id":"Meminta kepala panti untuk memberikan instruksi.","reason":"Salah. Melewati ketua unit dan langsung ke kepala panti tidak tepat sebagai langkah pertama."},{"jp":"Ｃ{介護福祉職|かいごふくししょく}に{対|たい}して，{介助方法|かいじょほうほう}について{教|おし}える。","id":"Mengajari C cara memberikan bantuan perawatan.","reason":"Salah. Belum diketahui apakah masalah C terkait cara perawatan."}],"explain":"フォロワーシップ (followership) = cara anggota tim mendukung pemimpin secara aktif. Langkah pertama adalah memahami kekhawatiran dan maksud pemimpin (ユニットリーダー), baru kemudian bertindak. Kata kunci {最初|さいしょ}に (pertama kali) di soal."}]}});

